package com.reactnativecommunity.blurview;

import android.view.View;
import android.view.ViewGroup;
import com.facebook.react.uimanager.ThemedReactContext;

import eightbitlab.com.blurview.BlurView;

import javax.annotation.Nonnull;

@SuppressWarnings("unused")
class BlurViewManagerImpl {

  public static final String REACT_CLASS = "AndroidBlurView";
  public static final int defaultRadius = 10;
  public static final int defaultSampling = 10;

  // A React Native Modal owns another Window. Its content and clear drawable
  // become known on attachment, never from ThemedReactContext's Activity.
  private static final class WindowBlurView extends BlurView {
    private float radius = defaultRadius;
    private boolean autoUpdate = true;
    private boolean enabled = true;
    private boolean configured;

    WindowBlurView(ThemedReactContext context) {
      super(context);
    }

    @Override
    protected void onAttachedToWindow() {
      configured = false;
      View root = getRootView();
      if (root instanceof ViewGroup) {
        ViewGroup content = root.findViewById(android.R.id.content);
        if (content == null) content = (ViewGroup) root;
        // setupWith destroys the old controller before binding this Window.
        setupWith(content)
          .setFrameClearDrawable(root.getBackground())
          .setBlurRadius(radius);
        configured = true;
      }
      super.onAttachedToWindow();
      applyState();
    }

    @Override
    protected void onDetachedFromWindow() {
      super.onDetachedFromWindow();
      configured = false;
    }

    private void applyState() {
      super.setBlurEnabled(configured && enabled);
      super.setBlurAutoUpdate(configured && enabled && autoUpdate && isHardwareAccelerated());
    }

    void updateRadius(int value) {
      radius = value;
      if (configured) super.setBlurRadius(value);
      invalidate();
    }

    void updateAutoUpdate(boolean value) {
      autoUpdate = value;
      if (configured) applyState();
      invalidate();
    }

    void updateEnabled(boolean value) {
      enabled = value;
      if (configured) applyState();
    }
  }

  public static @Nonnull BlurView createViewInstance(@Nonnull ThemedReactContext ctx) {
    return new WindowBlurView(ctx);
  }

  public static void setRadius(BlurView view, int radius) {
    ((WindowBlurView) view).updateRadius(radius);
  }

  public static void setColor(BlurView view, int color) {
    view.setOverlayColor(color);
    view.invalidate();
  }

  public static void setDownsampleFactor(BlurView view, int factor) {}

  public static void setAutoUpdate(BlurView view, boolean autoUpdate) {
    ((WindowBlurView) view).updateAutoUpdate(autoUpdate);
  }

  public static void setBlurEnabled(BlurView view, boolean enabled) {
    ((WindowBlurView) view).updateEnabled(enabled);
  }
}
